from typing import Any, Dict
from task_orchestrator.state import TaskState

def planner_node(state: TaskState) -> Dict[str, Any]:
    """Generates a plan based on the goal."""
    print("--- PLANNER ---")
    goal = state.get("goal", "")
    # Simple simulation of planning
    plan = [
        f"Step 1: Analyze {goal}",
        f"Step 2: Implement core logic for {goal}",
        f"Step 3: Test and verify {goal}"
    ]
    return {
        "plan": plan,
        "status": "planned",
        "iteration": 0
    }

def executor_node(state: TaskState) -> Dict[str, Any]:
    """Executes the next step in the plan."""
    print("--- EXECUTOR ---")
    plan = state.get("plan", [])
    results = state.get("results", [])
    iteration = state.get("iteration", 0)

    if iteration < len(plan):
        current_step = plan[iteration]
        result = f"Completed: {current_step}"
        return {
            "results": [result],
            "iteration": iteration + 1,
            "status": "executing"
        }

    return {"status": "all_steps_attempted"}

def qa_node(state: TaskState) -> Dict[str, Any]:
    """Evaluates the results and decides if done."""
    print("--- QA ---")
    plan = state.get("plan", [])
    iteration = state.get("iteration", 0)

    if iteration >= len(plan):
        return {"status": "finished"}
    else:
        return {"status": "continue"}
